using Kards.Ui.Contracts;
using Kards.Ui.Core;
using Kards.Ui.OrcBridge;
using Orc.Game.Cards;
using Orc.Game.Commanding;
using Orc.Game.Effects;
using Xunit;

namespace Kards.Ui.Tests;

// Frozen demo definitions from the saved workshop, not regenerated by the seed tool.
[Collection("Workshop")]
public sealed class SavedDemoMechanicsTests : IDisposable
{
    private readonly string root = Path.Combine(Path.GetTempPath(), "orc-saved-mechanics-" + Guid.NewGuid().ToString("N"));
    private readonly CardCatalog catalog = new();
    private readonly DiyCardLibrary cards;
    private readonly DiyWorkshopLibrary packs;
    private const string Source = @"H:\Working Folder\OrC-KSD.Godot\proto\data\nations";
    public SavedDemoMechanicsTests()
    {
        Directory.CreateDirectory(root);
        foreach (var name in new[] { "packs", "cards" })
        {
            using var input = typeof(SavedDemoMechanicsTests).Assembly.GetManifestResourceStream($"DemoMechanics.{name}.json")!;
            using var output = File.Create(Path.Combine(root, name + ".json")); input.CopyTo(output);
        }
        packs = new(Path.Combine(root, "packs.json")); cards = new(Path.Combine(root, "cards.json"));
        Assert.Null(packs.LoadError); Assert.Null(cards.LoadError);
        catalog.Load(Source); OrcEngineHost.Reset(); OrcEngineHost.WarmUp(Path.Combine(Path.GetDirectoryName(Source)!, "kards"));
        WorkshopAuthoring.Configure(packs, cards.Cards); Assert.Empty(WorkshopAuthoring.Errors);
    }
    private async Task<OrcMatchSession> Ready(params string[] hand)
    {
        var s = await OrcMatchSession.CreateFromCatalogAsync(catalog.Cards, 31, "saved-mechanics", "unused",
            sourceDirectory: Source, openingHand: hand.Select(id => "diy/demo-" + id).ToArray(), customCards: cards.Cards, firstPlayerIndex: 0);
        s.DriveOpponent = false; await s.SettleMulliganAsync(false); await OrcDragVerification.FundAsync(s); return s;
    }
    private static CardBase Card(OrcMatchSession s, string suffix) => (CardBase)s.Host.Index[s.View.SelfHand.First(c => c.CardId == "diy/demo-" + suffix).Uid];
    private static async Task<UnitCard> Deploy(OrcMatchSession s, string suffix)
    {
        var c = Card(s, suffix);
        Assert.Equal(UiSubmitOutcome.Applied, await s.SubmitAsync(new PlayCard(OrcRefs.KeyOf(c))).WaitAsync(TimeSpan.FromSeconds(5)));
        s.SettleProjection(); return (UnitCard)c;
    }
    private static int Attack(CardBase c) => c.Modifiers.GetEffectiveValue(CardStatFields.Attack);
    private static int Health(CardBase c) => c.Modifiers.GetEffectiveValue(CardStatFields.Defense);
    private static void Choose(OrcMatchSession s, CardBase target) => s.TargetRequested += (request, responder) =>
        Assert.True(responder.Complete(request.RequestId, new Dictionary<string, IReadOnlyList<string>> { [request.Slots.Single().Name] = [OrcRefs.KeyOf(target)] }));

    [Fact]
    public async Task AllSavedKeywordsMountAsExecutablePrograms()
    {
        using var s = await Ready("mijia", "youji", "jidong", "buqu");
        foreach (var draft in cards.Cards)
        {
            var card = await s.Host.Match.CardService.CreateAsync(draft.Id, s.Host.Viewer);
            Assert.Equal(draft.Keywords.Length, KeywordProgramRuntime.Components(card).Length);
        }
    }
    [Fact]
    public async Task GuerrillaCreatesExactlyOneTemporaryCopyWithoutGuerrilla()
    {
        using var s = await Ready("youji"); var unit = await Deploy(s, "youji");
        var copies = s.Host.Viewer.Hand.OfType<CardBase>().Where(c => c.Definition == unit.Definition).ToArray();
        var copy = Assert.Single(copies); Assert.Empty(KeywordProgramRuntime.Components(copy));
        await s.Host.Match.EndTurn(); Assert.DoesNotContain(copy, s.Host.Viewer.Hand);
        Assert.False(unit.GetData<UnitStateData>().IsDestroyed);
    }
    [Fact]
    public async Task ReinforcementCountsRealEntriesAndBuffsOnTheSecondEntry()
    {
        var bounce = new DiyKeywordDraft { Id = "kw-test-bounce", Name = "测试回手", ProgramJson = new KeywordProgram
        { Skills = [new() { Id = "return", Name = "回手", Cost = "0", SpendMove = false, SpendAttack = false,
            Actions = [new() { Op = "return.hand", KeepHistory = true }] }] }.ToJson() };
        packs.Save(packs.Packs.Single() with { Keywords = [.. packs.Packs.Single().Keywords, bounce] });
        var draft = cards.Cards.Single(c => c.Id == "diy/demo-mijia");
        cards.Save(draft with { Keywords = [.. draft.Keywords, bounce.Id] });
        WorkshopAuthoring.Configure(packs, cards.Cards);
        using var s = await Ready("mijia"); var unit = await Deploy(s, "mijia"); var before = Attack(unit);
        Assert.Equal(draft.Attack, before);
        var component = KeywordProgramRuntime.Components(unit).Single(c => c.Definition.Skills.Length > 0);
        Assert.True(await component.UseAsync("return")); s.SettleProjection();
        // Guerrilla also leaves a temporary copy; select the returned instance carrying entry history.
        var returned = s.Host.Viewer.Hand.OfType<CardBase>().Single(c => c.Definition == unit.Definition && KeywordProgramRuntime.Components(c).Any(p => p.Entries == 1));
        Assert.Equal(UiSubmitOutcome.Applied, await s.SubmitAsync(new PlayCard(OrcRefs.KeyOf(returned))));
        Assert.Equal(before + 2, Attack(returned)); Assert.Equal(draft.Defense + 2, Health(returned));
    }
    [Fact]
    public async Task UnyieldingPreventsOneDeathThenDiesOnTheOwnersNextTurn()
    {
        using var s = await Ready("buqu"); var unit = await Deploy(s, "buqu");
        await EffectRuntime.ResolveFor(unit)!.DamageAsync(unit, 100);
        Assert.False(unit.GetData<UnitStateData>().IsDestroyed); Assert.Equal(1, Health(unit));
        await OrcDragVerification.CycleTurnAsync(s); Assert.True(unit.GetData<UnitStateData>().IsDestroyed);
    }
    [Fact]
    public async Task StrategyReplacesTheDyingUnitOnceWithoutLeavingItsBody()
    {
        using var s = await Ready("zhanlve"); var unit = await Deploy(s, "zhanlve");
        await EffectRuntime.ResolveFor(unit)!.DamageAsync(unit, 100);
        var row = s.Host.Match.Battlefield.PlayerASupportLine.Members.OfType<UnitCard>().ToArray();
        Assert.DoesNotContain(unit, row); Assert.Equal("溃军", Assert.Single(row).Name);
    }
    [Fact]
    public async Task DemobilizationCopiesOnlyNonDeathDeparturesAndRemovesItself()
    {
        using var s = await Ready("fuyuan"); var unit = await Deploy(s, "fuyuan");
        await s.Host.Match.CommandManager.LeaveBattlefieldAsync(unit);
        var copy = Assert.Single(s.Host.Viewer.Hand.OfType<CardBase>(), c => c.Definition == unit.Definition);
        Assert.Empty(KeywordProgramRuntime.Components(copy)); Assert.Empty(KeywordProgramRuntime.Components(unit));
        Assert.Equal(4, copy.Modifiers.GetEffectiveValue(CardStatFields.DeployCost));
    }
    [Fact]
    public async Task GrappleLocksBothUnitsFightsAcrossSupportLinesAndUnlocksTheSurvivor()
    {
        using var s = await Ready("chandou");
        var uid = await OrcDragVerification.JoinSupportAsync(s, 1, "diy/demo-jidong"); s.SettleProjection();
        var enemy = (UnitCard)s.Host.Index[uid]; Choose(s, enemy); var unit = await Deploy(s, "chandou");
        Assert.Equal(0, KeywordProgramRuntime.Resolve(unit, "move.allowed", 1));
        Assert.Equal(0, KeywordProgramRuntime.Resolve(enemy, "attack.allowed", 1));
        await OrcDragVerification.CycleTurnAsync(s);
        Assert.True(unit.GetData<UnitStateData>().IsDestroyed); Assert.Equal(1, Health(enemy));
        Assert.Equal(1, KeywordProgramRuntime.Resolve(enemy, "attack.allowed", 1));
    }
    [Fact]
    public async Task LoadCreatesOneLaunchWithCapturedAttackAndLaunchDealsThatDamageOnce()
    {
        using var s = await Ready("buqu", "zhuangtian"); var unit = await Deploy(s, "buqu");
        var order = Card(s, "zhuangtian"); var count = s.Host.Viewer.Hand.Count;
        Assert.Equal(UiSubmitOutcome.Applied, await s.SubmitAsync(new PlayCard(OrcRefs.KeyOf(order), TargetUid: OrcRefs.KeyOf(unit))).WaitAsync(TimeSpan.FromSeconds(5)));
        s.SettleProjection(); Assert.Equal(count, s.Host.Viewer.Hand.Count);
        var launch = Card(s, "fashe"); Assert.Equal(Attack(unit), launch.GetData<KeywordProgramData>().Values["damage"]);
        var before = Health(unit);
        Assert.Equal(UiSubmitOutcome.Applied, await s.SubmitAsync(new PlayCard(OrcRefs.KeyOf(launch), TargetUid: OrcRefs.KeyOf(unit))).WaitAsync(TimeSpan.FromSeconds(5)));
        Assert.Equal(before - Attack(unit), Health(unit));
    }
    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task MobilityAllowsTwoRealAttacksThenRemovesTheKeyword(bool auditFixture)
    {
        using var s = await Ready("jidong"); UnitCard unit;
        if (auditFixture)
        {
            var prepared = await OrcDragVerification.PrepareMovementAsync(s);
            unit = (UnitCard)s.Host.Index[prepared.MobileUid];
        }
        else
        {
            unit = await Deploy(s, "jidong");
            await OrcDragVerification.CycleTurnAsync(s); s.SettleProjection();
            Assert.Equal(UiSubmitOutcome.Applied, await s.SubmitAsync(new MoveUnit(OrcRefs.KeyOf(unit), "frontline", 0)));
            await OrcDragVerification.CycleTurnAsync(s); s.SettleProjection();
        }
        var health = s.Host.Match.Players[1].Hq.Health;
        for (var i = 0; i < 2; i++) Assert.Equal(UiSubmitOutcome.Applied, await s.SubmitAsync(new CommandUnit(OrcRefs.KeyOf(unit), TargetUid: OrcRefs.KeyOf(s.Host.Match.Players[1].Hq))).WaitAsync(TimeSpan.FromSeconds(5)));
        Assert.Equal(health - 2 * Attack(unit), s.Host.Match.Players[1].Hq.Health);
        Assert.Empty(KeywordProgramRuntime.Components(unit)); Assert.False(unit.GetData<CommandData>().CanAttack);
    }
    [Fact]
    public async Task RetreatUsesNormalMovementAndConsumesItsCostAndOpportunity()
    {
        using var s = await Ready("kuijun"); var unit = await Deploy(s, "kuijun");
        await OrcDragVerification.CycleTurnAsync(s); s.SettleProjection();
        Assert.Equal(UiSubmitOutcome.Applied, await s.SubmitAsync(new MoveUnit(OrcRefs.KeyOf(unit), "frontline", 0)));
        await OrcDragVerification.CycleTurnAsync(s); s.SettleProjection(); var points = s.Host.Viewer.Points;
        Assert.Equal(UiSubmitOutcome.Applied, await s.SubmitAsync(new MoveUnit(OrcRefs.KeyOf(unit), "support", 0)));
        OrcDragVerification.AssertRetreated(s, OrcRefs.KeyOf(unit), points);
    }
    [Fact]
    public async Task TigerTransformsTheSurvivingEnemyAfterOneNormalAttack()
    {
        using var s = await Ready("hushi"); var unit = await Deploy(s, "hushi");
        var uid = await OrcDragVerification.JoinSupportAsync(s, 1, "diy/demo-buqu");
        var enemy = (UnitCard)s.Host.Index[uid]; await OrcDragVerification.CycleTurnAsync(s); s.SettleProjection();
        Assert.Equal(UiSubmitOutcome.Applied, await s.SubmitAsync(new MoveUnit(OrcRefs.KeyOf(unit), "frontline", 0)));
        await OrcDragVerification.CycleTurnAsync(s); s.SettleProjection();
        var errors = new List<string>(); s.Host.ErrorRaised += errors.Add;
        var points = s.Host.Viewer.Points;
        var outcome = await s.SubmitAsync(new CommandUnit(OrcRefs.KeyOf(unit), uid)); s.Pump();
        Assert.True(outcome == UiSubmitOutcome.Applied, $"{outcome}: {s.LastRejectionReason}; attacker={Attack(unit)}/{Health(unit)} alive={unit.Life.IsAlive}; target={Health(enemy)} alive={enemy.Life.IsAlive}; errors={string.Join(" | ", errors)}");
        Assert.DoesNotContain(enemy, s.Host.Match.Battlefield.PlayerBSupportLine.Members);
        Assert.Equal("溃军", Assert.Single(s.Host.Match.Battlefield.PlayerBSupportLine.Members.OfType<UnitCard>()).Name);
        Assert.Equal(points - unit.Modifiers.GetEffectiveValue(CardStatFields.OperateCost), s.Host.Viewer.Points);
        Assert.False(unit.GetData<CommandData>().CanAttack); Assert.Empty(errors);
    }
    [Fact]
    public async Task DemobilizationDoesNotCopyAUnitThatIsKilled()
    {
        using var s = await Ready("fuyuan"); var unit = await Deploy(s, "fuyuan");
        await EffectRuntime.ResolveFor(unit)!.KillAsync(unit);
        Assert.True(unit.GetData<UnitStateData>().IsDestroyed);
        Assert.DoesNotContain(s.Host.Viewer.Hand.OfType<CardBase>(), c => c.Definition == unit.Definition);
    }
    [Fact]
    public async Task StandaloneLaunchUsesTheSavedCardParameterExactlyOnce()
    {
        using var s = await Ready("buqu", "fashe"); var unit = await Deploy(s, "buqu"); var order = Card(s, "fashe");
        var component = Assert.Single(KeywordProgramRuntime.Components(order)); var damage = component.Number("value"); var before = Health(unit);
        Assert.Equal(UiSubmitOutcome.Applied, await s.SubmitAsync(new PlayCard(OrcRefs.KeyOf(order), TargetUid: OrcRefs.KeyOf(unit))).WaitAsync(TimeSpan.FromSeconds(5)));
        Assert.Equal(before - damage, Health(unit));
    }
    [Theory]
    [InlineData("zhuangtian")]
    [InlineData("fashe")]
    public async Task CancellingAnOrderDoesNotPayOrCreateAnythingAndRetryAsksOnce(string suffix)
    {
        using var s = await Ready("buqu", suffix); var unit = await Deploy(s, "buqu"); var order = Card(s, suffix);
        var cancel = true; var prompts = 0; var points = s.Host.Viewer.Points; var count = s.Host.Viewer.Hand.Count; var health = Health(unit);
        s.TargetRequested += (request, responder) =>
        {
            prompts++;
            if (cancel) Assert.True(responder.Cancel(request.RequestId));
            else Assert.True(responder.Complete(request.RequestId, new Dictionary<string, IReadOnlyList<string>> { [request.Slots.Single().Name] = [OrcRefs.KeyOf(unit)] }));
        };
        Assert.Equal(UiSubmitOutcome.Rejected, await s.SubmitAsync(new PlayCard(OrcRefs.KeyOf(order))).WaitAsync(TimeSpan.FromSeconds(5)));
        Assert.Equal(points, s.Host.Viewer.Points); Assert.Equal(count, s.Host.Viewer.Hand.Count); Assert.Equal(health, Health(unit));
        Assert.Equal(1, prompts); cancel = false;
        Assert.Equal(UiSubmitOutcome.Applied, await s.SubmitAsync(new PlayCard(OrcRefs.KeyOf(order))).WaitAsync(TimeSpan.FromSeconds(5)));
        Assert.Equal(2, prompts);
    }
    public void Dispose()
    {
        WorkshopAuthoring.Configure(new DiyWorkshopLibrary(Path.Combine(root, "empty.json")), []); OrcEngineHost.Reset();
        if (!Path.GetFullPath(root).StartsWith(Path.GetFullPath(Path.GetTempPath()), StringComparison.OrdinalIgnoreCase)) throw new IOException("Unexpected test directory");
        Directory.Delete(root, true);
    }
}
